require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();oecrm_require_permission($conn,'activity_audit','export');$companyId=oecrm_current_company_id($conn);$module=trim($_GET['module']??'');$actorType=trim($_GET['actor_type']??'');$employeeId=max(0,(int)($_GET['employee_id']??0));$risk=trim($_GET['risk']??'');$from=$_GET['from']??date('Y-m-d',strtotime('-30 days'));$to=$_GET['to']??date('Y-m-d');$where=['a.company_id='.(int)$companyId,"a.created_at>='".mysqli_real_escape_string($conn,$from)." 00:00:00'","a.created_at<='".mysqli_real_escape_string($conn,$to)." 23:59:59'"];if($module!=='')$where[]="a.module_key='".mysqli_real_escape_string($conn,$module)."'";if(in_array($actorType,['admin','employee','system'],true))$where[]="a.actor_type='$actorType'";if($employeeId)$where[]='a.employee_id='.(int)$employeeId;if(in_array($risk,['normal','review','suspicious'],true))$where[]="a.risk_level='$risk'";$rows=mysqli_query($conn,'SELECT a.*,e.employeeCode,e.name employee_name FROM audit_logs a LEFT JOIN employeestbl e ON e.id=a.employee_id WHERE '.implode(' AND ',$where).' ORDER BY a.id DESC');header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="activity-audit-'.$from.'-to-'.$to.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Date','Actor Type','Actor ID','Employee Code','Employee','Module','Action','Description','Entity Type','Entity ID','IP','Browser','Device','Platform','Risk','Risk Reasons','Before','After','Request']);while($r=mysqli_fetch_assoc($rows))fputcsv($out,[$r['created_at'],$r['actor_type'],$r['actor_id'],$r['employeeCode'],$r['employee_name'],$r['module_key'],$r['action'],$r['description'],$r['entity_type'],$r['entity_id'],$r['ip_address'],$r['browser_name'],$r['device_type'],$r['platform_name'],$r['risk_level'],$r['risk_reasons'],$r['old_values'],$r['new_values'],$r['request_method'].' '.$r['request_uri']]);fclose($out);oecrm_audit($conn,'activity_audit','export','audit_logs',null,'Activity audit CSV exported',null,['from'=>$from,'to'=>$to]);exit;
